import json,torch; print(torch.__version__)
for xd in (torch.float32,torch.bfloat16):
 for wd in (torch.float32,torch.bfloat16):
  for enabled in (False,True):
   x=torch.arange(16,device="cuda",dtype=xd).reshape(2,8); w=torch.ones(8,device="cuda",dtype=wd); row={"input":str(xd),"weight":str(wd),"autocast_bf16":enabled}
   try:
    with torch.autocast("cuda",dtype=torch.bfloat16,enabled=enabled): y=torch.nn.functional.layer_norm(x,(8,),w)
    row["output"]=str(y.dtype)
   except RuntimeError as e: row["error"]=str(e)[:160]
   print(json.dumps(row))
